class Stock {
    private int stock;
    Stock(int stock) { this.stock = stock; }
    boolean take(int amount) {
        if (amount <= 0 || amount > stock) return false;
        stock = stock - amount;
        return true;
    }
    int getStock() { return stock; }
}

class Stock:
    def __init__(self, stock):
        self._stock = stock
    def take(self, amount):
        if amount <= 0 or amount > self._stock:
            return False
        self._stock -= amount
        return True
    def available(self):
        return self._stock

